CustomField.formula:
IF(
/*If Account is Country Parent, stores (Regional) Top 50 Accounts value */
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'), Strategic_Account__c,
IF(
/*If Account is Sales site, stores Country Parent Account's (Regional) Top 50 Accounts by traversing one level up the hierarchy*/
AND(ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'),NOT(ISBLANK(ParentId))), Parent.Strategic_Account__c,
IF(
/*If Account is Parent HQ, stores Country Parent Account's (Regional) Top 50 Accounts by traversing one level up the hierarchy*/
ISPICKVAL(IM_Hierarchy_Level__c, 'Parent HQ'), Parent.Strategic_Account__c,Strategic_Account__c)))
